    },
    {
      "severity": "high",
      "file": "ui/src/components/Dashboard.tsx",
      "issue": "No navigation to the Profile screen – the spec requires a persistent bottom‑nav (Dashboard | Profile) on mobile and a top‑nav on desktop.",
      "fix": "Implement a <nav> component with tabs linking to \"/dashboard\" and \"/profile\". Use react‑router <Link> for SPA navigation and style it with the design tokens."
