{"path":"backend/app/database.py","content":""""Database session handling for FastAPI app with dynamic engine creation per request."""

from sqlalchemy import create_engine as _create_engine
from sqlalchemy.orm import sessionmaker, declarative_base
from .config import settings

Base = declarative_base()

def get_engine():
    """Create a new SQLAlchemy engine based on the current DATABASE_URL setting."""
    connect_args = {"check_same_thread": False} if "sqlite" in settings.DATABASE_URL else {}
    return _create_engine(settings.DATABASE_URL, connect_args=connect_args)

def get_db():
    """FastAPI dependency that provides a fresh DB session per request."""
    engine = get_engine()
    SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()
"}

{"path": "ui/src/components/Login.tsx", "content": "import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import api from '../services/api';

const Login: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const resp = await api.post('/login', new URLSearchParams({ username: email, password }));
      localStorage.setItem('access_token', resp.data.access_token);
      navigate('/dashboard');
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <main style={{ maxWidth: 420, margin: '64px auto', padding: 16 }}>
      <h1>Log in to your account</h1>
      {error && <div role="alert" style={{ color: 'red' }}>{error}</div>}
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="email">Email address</label>
          <input id="email" type="email" value={email} onChange={e => setEmail(e.target.value)} required autoComplete="email" placeholder="you@example.com" />
        </div>
        <div>
          <label htmlFor="password">Password</label>
          <input id="password" type="password" value={password} onChange={e => setPassword(e.target.value)} required autoComplete="current-password" placeholder="********" />
        </div>
        <button type="submit" disabled={!email || !password || loading}>
          {loading ? 'Signing in…' : 'Log in'}
        </button>
      </form>
      <p>Don’t have an account? <Link to="/register">Create account</Link></p>
    </main>
  );
};

export default Login;
"}

